import { createFileRoute, Link } from '@tanstack/react-router'
// import { useState, useEffect } from 'react'
// import { TPost } from '@/types'
// import { getPostsByCategory } from '@/data/posts'

// import PageSkeleton from '@/components/page-skeleton'
import SectionMagazine10 from '@/components/SectionMagazine10'
import Trening from '@/components/trending'
import Latest from '@/components/latest'
import Weekly from '@/components/weekly'
import ButtonPrimary from '@/shared/ButtonPrimary'
import _ from 'lodash'
import { useRef, useEffect } from 'react'
import { useGetLastPost } from '@/query/post/getLast'
import { useGetTopPost } from '@/query/post/getTop'
import { useGetTrending } from '@/query/post/getTrendingByTime'
import LastCategoryHome from '@/components/lastCatHome'
import AdsSliderMulti from '@/components/adsSliderMulti'
import { metaNewsHome } from '@/static'

const LANG_CONFIG = {
  fr: {
    dir: 'ltr',
    topCategoryId: '6220',
    trendingCategoryId: '1',
    latestHeading: 'Dernières News',
    moreNews: 'Plus de News',
    latestSlug: 'dernieres-actualites',
    categories: [
      'fibladiplus',
      'info',
      'economie',
      'telecoms-tic',
      'sport',
      'sante',
      'automobile-transport',
    ],
  },
  ar: {
    dir: 'rtl',
    topCategoryId: '7134',
    trendingCategoryId: '2',
    latestHeading: 'آخر أخبار الصحافة',
    moreNews: 'المزيد من الأخبار',
    latestSlug: 'آخر-الأخبار',
    categories: [
      'plus',
      'أخبار',
      'اقتصاد',
      'تكنولوجيا-و-علوم',
      'صحة',
      'رياضة',
      'نقل-و-سيارات',
    ],
  },
} as const

export const Route = createFileRoute('/news/ar/')({
  component: App,

  head: () => ({
    meta: metaNewsHome['ar'],
  }),
})

function App() {
  const lang = 'ar'
  const cfg = LANG_CONFIG[lang]

  const { data: dataTop, isLoading: isLoadingTop } = useGetTopPost(
    cfg.topCategoryId,
    '1',
  )

  const { data: dataLast, isLoading: isLoadingLast } = useGetLastPost(lang, '1')

  const { data: dataweek, isLoading: isLoadingweek } = useGetTrending(
    '7j',
    cfg.trendingCategoryId,
    false,
    10,
  )

  const { data: dataday, isLoading: isLoadingday } = useGetTrending(
    '6h',
    cfg.trendingCategoryId,
    true,
    10,
  )

  const topPosts = dataTop?.posts ?? []
  const lastPosts = dataLast?.posts ?? []
  const weekPosts = dataweek?.posts ?? []
  const dayPosts = dataday?.posts ?? []

  const sliderDev = useRef<HTMLDivElement>(
    null,
  ) as React.RefObject<HTMLDivElement>

  useEffect(() => {
    const handleScroll = _.throttle(() => {
      const side = sliderDev.current

      if (
        window.innerWidth > 1000 &&
        window.scrollY > side.clientHeight - window.innerHeight + 50
      ) {
        side.style.position = 'sticky'
        side.style.top = `-${side.clientHeight - window.innerHeight + 50}px`
      } else {
        side.style.position = ''
        side.style.top = '0px'
      }
    }, 100)

    window.addEventListener('scroll', handleScroll)
    return () => window.removeEventListener('scroll', handleScroll)
  }, [])

  return (
    <div className="relative space-y-14" dir={cfg.dir}>
      <div className="relative container mt-4 space-y-28 lg:mt-0 lg:space-y-32">
        <SectionMagazine10
          posts={topPosts}
          vr={lang}
          loading={isLoadingTop}
          isHome
        />
      </div>

      <div className="space-y-6">
        <div className="container space-y-28 lg:space-y-32">
          <div className="section-post-with-widgets relative">
            <div className="flex flex-col space-y-8 lg:flex-row ">
              <div className="w-full  -mt-5">
                <AdsSliderMulti />
                <Trening posts={dayPosts} vr={lang} loading={isLoadingday} />
                {isLoadingTop && (
                  <>
                    <div className="space-y-4">
                      <div className="bg-gray-300 h-7 w-1/2 rounded"></div>
                      <div className="grid grid-cols-1 sm:grid-cols-4 gap-8">
                        {[1, 2, 3, 4].map((_, index) => (
                          <div>
                            <div
                              key={index}
                              className="animate-pulse rounded-3xl overflow-hidden "
                            >
                              <div className="bg-gray-300 h-32 sm:h-44 w-full"></div>
                            </div>

                            <div className="py-4 space-y-2">
                              <div className="bg-gray-300 h-5 w-full rounded"></div>
                              <div className="bg-gray-300 h-5 w-5/6 rounded"></div>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                    <div className="space-y-4">
                      <div className="bg-gray-300 h-7 w-1/2 rounded"></div>
                      <div className="grid grid-cols-1 sm:grid-cols-4 gap-8">
                        {[1, 2, 3, 4].map((_, index) => (
                          <div>
                            <div
                              key={index}
                              className="animate-pulse rounded-3xl overflow-hidden "
                            >
                              <div className="bg-gray-300 h-32 sm:h-44 w-full"></div>
                            </div>

                            <div className="py-4 space-y-2">
                              <div className="bg-gray-300 h-5 w-full rounded"></div>
                              <div className="bg-gray-300 h-5 w-5/6 rounded"></div>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  </>
                )}
                {!isLoadingTop &&
                  cfg.categories.map((slug) => (
                    <LastCategoryHome
                      key={slug}
                      vr={lang}
                      categorySlug={slug}
                    />
                  ))}
              </div>
            </div>
          </div>
        </div>
        <div className="container space-y-28 lg:space-y-32">
          <div className="section-post-with-widgets relative">
            <div className="flex flex-col space-y-8 lg:flex-row ">
              <div className="w-full lg:w-3/5 xl:w-2/3 xl:pe-14 -mt-4">
                {isLoadingLast && (
                  <div className="my-10 h-7 w-1/2 bg-gray-300"></div>
                )}
                <Latest
                  loading={isLoadingLast}
                  posts={lastPosts}
                  heading={cfg.latestHeading}
                  vr={lang}
                />

                <div className="mt-8 flex justify-center cursor-pointer">
                  <Link
                    to="/news/$postId/page/$pagenumber"
                    params={{
                      postId: cfg.latestSlug,
                      pagenumber: '2',
                    }}
                    className="flex items-center space-x-4 w-full"
                  >
                    <ButtonPrimary className="cursor-pointer w-full">
                      {cfg.moreNews}
                    </ButtonPrimary>
                  </Link>
                </div>
              </div>

              <div className="w-full lg:w-2/5 xl:w-1/3 mb-8">
                <div className="space-y-7  " ref={sliderDev}>
                  <Weekly
                    loading={isLoadingweek}
                    posts={weekPosts}
                    full
                    vr={lang}
                  />
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}
